@extends('layouts.app') @section('title',$course->exists?'Edit course':'Create course') @section('heading',$course->exists?'Edit course':'Create a course') @section('content')<div class="panel form-panel"><form method="POST" action="{{ $course->exists?route('courses.update',$course):route('courses.store') }}">@csrf @if($course->exists)@method('PUT')@endif<div class="stack-form"><label>Course title</label><input name="title" value="{{ old('title',$course->title) }}" required><label>Description</label><textarea name="description" rows="5">{{ old('description',$course->description) }}</textarea><label>Course category</label><select name="course_category_id"><option value="">Choose category</option>@foreach($categories as $cat)<option value="{{ $cat->id }}" @selected(old('course_category_id',$course->course_category_id)==$cat->id)>{{ $cat->name }}</option>@endforeach</select><label>Required membership level (optional)</label><select name="required_membership_level_id"><option value="">Open to all students</option>@foreach($levels as $level)<option value="{{ $level->id }}" @selected(old('required_membership_level_id',$course->required_membership_level_id)==$level->id)>{{ $level->name }}</option>@endforeach</select><label>Publication status</label><select name="status"><option value="draft" @selected(old('status',$course->status)==='draft')>Draft</option><option value="published" @selected(old('status',$course->status)==='published')>Published</option><option value="archived" @selected(old('status',$course->status)==='archived')>Archived</option></select><div class="form-actions"><a href="{{ route('courses.manage') }}" class="btn-outline">Cancel</a><button class="btn-primary">Save course</button></div></div></form></div>@endsection
